/* Ép màu chữ trực tiếp (selector đơn giản, tương thích Stylus) */
[role="navigation"] span,
[role="complementary"] span,
[role="banner"] span,
a[role="link"] span,
[role="article"] div[dir="auto"],
[role="article"] span[dir="auto"] {
  color: #684657 !important;
}
/* Tiêu đề mục / chữ phụ */
[role="navigation"] h2 span,
[role="complementary"] h3 span,
[role="main"] h2 span,
[role="main"] h3 span {
  color: #8a6475 !important;
}
/* Nút xanh bên cột phải giữ chữ trắng */
[role="complementary"] [role="button"] span {
  color: #ffffff !important;
}
/* Đường phân cách */
hr, [role="separator"] {
  background-color: #f1d5e1 !important;
  border-color: #f1d5e1 !important;
}
